SET FOREIGN_KEY_CHECKS = 0;

-- 1. LIMPIEZA DE DATOS PREVIOS DE LA EMPRESA 2
DELETE FROM turnos WHERE empresa_id = 2;
DELETE FROM medical_records WHERE empresa_id = 2;
DELETE FROM profesionales_config WHERE empresa_id = 2;
DELETE FROM servicios WHERE empresa_id = 2;
DELETE FROM clients WHERE empresa_id = 2;
DELETE FROM users WHERE empresa_id = 2 AND id NOT IN (7, 8);

-- 2. ASEGURAR OBRAS SOCIALES EXISTENTES
ON DUPLICATE KEY UPDATE nombre=VALUES(nombre), cuit=VALUES(cuit), activo=VALUES(activo), updated_at=NOW();

-- TABLA: users
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `email`=VALUES(`email`), `role`=VALUES(`role`), `sub_role`=VALUES(`sub_role`), `activo`=VALUES(`activo`), `status`=VALUES(`status`), `consultorio`=VALUES(`consultorio`), `updated_at`=NOW();

